280:   if(length>.05)player.walk+=dt*10;
281:   camera.position.set(player.pos.x,player.pos.y+(length>.05?Math.sin(player.walk)*.025:0),player.pos.z);
282:   camera.rotation.set(player.pitch,player.yaw,0,'YXZ');
283:   rifle.position.y=Math.sin(player.walk)*.012;
284:   updateEnemies(dt,elapsed);
285:  }
286:  renderer.render(scene,camera);
287: }
288: window.addEventListener('resize',()=>{
